function extract($, ctx) {
  const items = [];

  // Locate all menu blocks (there may be duplicates for mobile/desktop)
  $('.menu').each((_, menuEl) => {
    let currentSection = null;

    // Process each section inside the menu
    $(menuEl).find('.menu-section').each((_, secEl) => {
      const $sec = $(secEl);
      const $titleDiv = $sec.find('.menu-section-header .menu-section-title');
      if ($titleDiv.length) {
        currentSection = cleanText($titleDiv.text());
      }

      // Process each item in the section
      $sec.find('.menu-items .menu-item').each((_, itemEl) => {
        const $item = $(itemEl);

        // Name
        const $nameDiv = $item.find('.menu-item-title');
        if (!$nameDiv.length) return;
        const name = cleanText($nameDiv.text());
        if (!name) return;

        // Description (optional)
        const $descDiv = $item.find('.menu-item-description');
        const description = $descDiv.length ? cleanText($descDiv.text()) : null;

        // Price – try top price first, then bottom
        let priceNum = null;
        const $priceTop = $item.find('.menu-item-price-top');
        if ($priceTop.length) {
          priceNum = parsePrice($priceTop.text());
        }
        if (priceNum === null) {
          const $priceBottom = $item.find('.menu-item-price-bottom');
          if ($priceBottom.length) {
            priceNum = parsePrice($priceBottom.text());
          }
        }

        items.push({
          section: currentSection,
          name,
          description,
          price: priceNum
        });
      });
    });
  });

  // Deduplicate exact duplicates (e.g., mobile + desktop copies)
  const seen = new Set();
  const deduped = [];
  for (const it of items) {
    const key = `${it.section ?? ''}|${it.name}|${it.description ?? ''}|${it.price ?? ''}`;
    if (!seen.has(key)) {
      seen.add(key);
      deduped.push(it);
    }
  }

  return deduped;
}
